document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('quiz-form');
    const statusMessage = document.getElementById('status-message');

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        // In a real app, we'd grade the quiz here.
        // For this demo, just show a submission message.

        statusMessage.textContent = "Quiz submitted successfully! Your answers have been recorded.";
        statusMessage.classList.remove('hidden');

        // Disable the form after submission
        const inputs = form.querySelectorAll('input, button');
        inputs.forEach(input => input.disabled = true);

        // Optionally, one could reset the form instead of disabling
        // form.reset();
        // setTimeout(() => statusMessage.classList.add('hidden'), 5000);
    });
});

