                        <input type="checkbox" id="q2-css" name="q2" value="css">
                        <label for="q2-css">CSS</label>
                    </div>
                    <div class="option">
                        <input type="checkbox" id="q2-sql" name="q2" value="sql">
                        <label for="q2-sql">SQL</label>
                    </div>
                </fieldset>
            </div>

            <div class="form-field">
